const PLACES = Object.fromEntries(Object.entries(RAW).map(([city, list]) => [
  city,
  list.map(([category, cost, fr, en, ar, descFr, descEn, descAr]) => {
    const id = `${city}-${slug(fr)}`;
    return {
      id, category, cost,
      name: { fr, en: en || fr, ar },
      description: { fr: descFr, en: descEn, ar: descAr },
      image: PHOTOS[id] ?? null,
    };
  }),
]));

const PLACE_CATEGORIES = ['monument', 'food', 'market', 'nature'];

module.exports = { PLACES, PLACE_CATEGORIES };
